# Ticketing settings per edition (decision 0012), carrying the speakers'
# Pretix settings over.
#
# Polling is the baseline (decision 0012): every edition with a provider
# API, every 15 minutes. The schedule is data, editable under "Periodic
# tasks"; seeding it here gives a fresh database the same default. The
# speakers' nightly Pretix reconcile did the same for Pretix alone and is
# switched off rather than deleted, so turning it back on is one tick.

# Generated by Django 5.2.13 on 2026-10-13 02:15

import django.db.models.deletion
from django.db import migrations, models

import speakers.encryption

TASK_NAME = "Poll ticketing registrations"
TASK_PATH = "ticketing.tasks.poll_registrations_task"
OLD_TASK_NAME = "Reconcile pretix orders for the speaker portal"


def seed(apps, schema_editor):
    IntervalSchedule = apps.get_model("django_celery_beat", "IntervalSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    every, _ = IntervalSchedule.objects.get_or_create(every=15, period="minutes")
    PeriodicTask.objects.get_or_create(
        name=TASK_NAME,
        defaults={
            "task": TASK_PATH,
            "interval": every,
            "description": (
                "Fetch registrations changed since the last run, for every "
                "edition with a ticketing API; webhooks only make it faster."
            ),
        },
    )
    PeriodicTask.objects.filter(name=OLD_TASK_NAME).update(enabled=False)


def unseed(apps, schema_editor):
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    PeriodicTask.objects.filter(name=TASK_NAME).delete()
    PeriodicTask.objects.filter(name=OLD_TASK_NAME).update(enabled=True)


def copy_speakers_pretix(apps, schema_editor):
    """Carry the speakers' per-edition Pretix settings over (decision 0012).
    A token or secret this deploy cannot decrypt is left behind: it could
    not be written again, and the edition reads as not configured anyway."""
    SpeakerSettings = apps.get_model("speakers", "SpeakerSettings")
    TicketingSettings = apps.get_model("ticketing", "TicketingSettings")
    for row in SpeakerSettings.objects.select_related("conference"):
        if not (row.pretix_organizer or row.pretix_api_token):
            continue

        def readable(value):
            return value if isinstance(value, str) else ""

        TicketingSettings.objects.get_or_create(
            conference=row.conference,
            defaults={
                "provider": "PRETIX",
                "base_url": row.pretix_base_url,
                "organizer": row.pretix_organizer,
                "event_id": row.pretix_event or row.conference.pretix_event_slug,
                "api_token": readable(row.pretix_api_token),
                "webhook_secret": readable(row.pretix_webhook_secret),
                "last_synced_at": row.pretix_last_synced_at,
            },
        )


